// Measures the profile generated by :baselineprofile against the app's release-like benchmarkRelease (#312).
plugins {
    id("com.android.test")
    // Creates benchmarkRelease (and the target app wiring) from the release build type.
    alias(libs.plugins.baselineprofile)
}

android {
    namespace = "dev.mateux.caparao.macrobenchmark"
    compileSdk = 37

    defaultConfig {
        minSdk = 31
        targetSdk = 37
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        // #312 runs the benchmarks on the emulator: the numbers are the tool's baseline, not a device comparison.
        testInstrumentationRunnerArguments["androidx.benchmark.suppressErrors"] = "EMULATOR"
    }

    targetProjectPath = ":app"

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

dependencies {
    implementation(libs.androidx.test.runner)
    implementation(libs.androidx.test.ext.junit)
    implementation(libs.uiautomator)
    implementation(libs.benchmark.macro.junit4)
}
